{"id":"combo-recipe-0.2","language":"en","title":"Synthetic single-axis bar-line combo","summary":"Synthetic single-axis bar-line combo","capabilityIds":["basic-0.2"],"schemaVersion":"0.2","source":"resources/recipes/combo.json","license":"Apache-2.0","updatedAt":"2026-10-31","uri":"chartnexus://recipes/combo/0.2","contentHash":"sha256:5d42f0b9d98d16d3b0ec56be6db8231444cda25082777f6204e09691b8b86b61","body":"{
  "schemaVersion": "0.2",
  "id": "sales",
  "mode": "intent",
  "data": {
    "kind": "inline",
    "fields": ["month", "sales", "cost"],
    "rows": [
      {
        "month": "Jan",
        "sales": 120,
        "cost": 90
      },
      {
        "month": "Feb",
        "sales": 180,
        "cost": 130
      },
      {
        "month": "Mar",
        "sales": 150,
        "cost": 110
      }
    ]
  },
  "chart": {
    "type": "combo",
    "title": "Sales and cost",
    "encoding": {
      "x": {
        "field": "month",
        "type": "ordinal"
      },
      "y": {
        "field": "sales",
        "type": "quantitative",
        "unit": {
          "kind": "currency",
          "code": "USD"
        }
      }
    },
    "secondary": {
      "field": "cost",
      "unit": {
        "kind": "currency",
        "code": "USD"
      }
    }
  },
  "presentation": {
    "legend": {
      "show": true
    }
  }
}
"}
{"id":"funnel-recipe-0.2","language":"en","title":"Synthetic ordered funnel chart","summary":"Synthetic ordered funnel chart","capabilityIds":["basic-0.2"],"schemaVersion":"0.2","source":"resources/recipes/funnel.json","license":"Apache-2.0","updatedAt":"2026-10-31","uri":"chartnexus://recipes/funnel/0.2","contentHash":"sha256:7804ba5c3180457ceb063b2290201f6247ade37ab4bfab652811c5d12873eb46","body":"{
