{"id":"native-strict-schema","language":"en","title":"Strict native option subset schema","summary":"Strict native option subset schema","capabilityIds":["native-strict-basic-0.1"],"schemaVersion":"0.1","source":"packages/schema/src/native-strict-basic-0.1.schema.json","license":"Apache-2.0","updatedAt":"2026-10-31","uri":"chartnexus://schema/native-strict-basic/0.1","contentHash":"sha256:d788b50db0d1d1cfe188b1a0e6429e6e8db7fe67d3ddf5a49290fe3049a786d2","body":"{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://chartnexus.dev/schemas/native-strict-basic/0.1",
  "title": "NativeStrictBasicOption",
  "description": "Experimental bounded subset of ECharts option, not the full ECharts schema.",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "title": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "text": {
          "type": "string",
          "maxLength": 256
        }
      }
    },
    "legend": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "show": {
          "type": "boolean"
        }
      }
    },
    "xAxis": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "type": {
          "enum": ["category", "value"]
        },
        "name": {
          "type": "string",
          "maxLength": 256
        },
        "data": {
          "type": "array",
          "maxItems": 10000,
          "items": {
            "type": "string",
            "maxLength": 256
          }
        }
      },
      "required": ["type"]
    },
    "yAxis": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "type": {
          "enum": ["category", "value"]
        },
        "name": {
          "type": "string",
          "maxLength": 256
        },
        "data": {
          "type": "array",
          "maxItems": 10000,
          "items": {
            "type": "string",
            "maxLength": 256
          }
        }
      },
      "required": ["type"]
    },
    "series": {
      "type": "array",
      "minItems": 1,
      "maxItems": 50,
      "items": {
        "oneOf": [
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "name": {
                "type": "string",
                "maxLength": 256
              },
              "id": {
                "type": "string",
                "maxLength": 256
              },
              "type": {
                "enum": ["bar", "line"]
              },
              "stack": {
                "type": "string",
                "maxLength": 256
              },
              "data": {
                "type": "array",
                "maxItems": 10000,
                "items": {
                  "type": ["number", "null"]
                }
              }
            },
            "required": ["type", "data"]
          },
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "name": {
                "type": "string",
                "maxLength": 256
              },
              "id": {
                "type": "string",
                "maxLength": 256
              },
              "type": {
                "const": "scatter"
              },
              "data": {
                "type": "array",
                "maxItems": 10000,
                "items": {
                  "type": "array",
                  "prefixItems": [
                    {
                      "type": "number"
                    },
                    {
                      "type": ["number", "null"]
                    }
                  ],
                  "items": false,
                  "minItems": 2,
                  "maxItems": 2
                }
              }
            },
            "required": ["type", "data"]
          },
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "name": {
                "type": "string",
                "maxLength": 256
              },
              "id": {
                "type": "string",
                "maxLength": 256
              },
              "type": {
                "const": "pie"
              },
              "data": {
                "type": "array",
                "maxItems": 10000,
                "items": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "name": {
                      "type": "string",
                      "maxLength": 256
                    },
                    "value": {
                      "type": "number",
                      "minimum": 0
                    }
                  },
                  "required": ["name", "value"]
                }
              }
            },
            "required": ["type", "data"]
          }
        ]
      }
    },
    "tooltip": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "show": {
          "type": "boolean"
        }
      }
    },
    "color": {
      "type": "array",
      "minItems": 1,
      "maxItems": 50,
      "items": {
        "type": "string",
        "pattern": "^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$"
      }
    },
    "backgroundColor": {
      "type": "string",
      "pattern": "^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$"
    }
  },
  "required": ["series"]
}
"}
{"id":"native-strict-capabilities","language":"en","title":"Strict native subset capabilities","summary":"Strict native subset capabilities","capabilityIds":["native-strict-basic-0.1"],"schemaVersion":"0.1","source":"packages/core/src/native-strict-capabilities.json","license":"Apache-2.0","updatedAt":"2026-10-31","uri":"chartnexus://capabilities/native-strict-basic-0.1","contentHash":"sha256:b80af1d98ceec5c6e54ee10d8adad7228b738774256185c6eab80c6895690d97","body":"{
  "id": "native-strict-basic-0.1",
  "status": "experimental",
  "schemaVersion": "0.1",
  "mode": "echarts",
  "validation": "strict-subset",
  "chartShapes": ["bar-line-category", "scatter-value", "single-pie"],
  "optionSchema": "chartnexus://schema/native-strict-basic/0.1",
  "restrictions": [
    "unknown fields rejected",
    "explicit series data",
    "no dataset",
    "no formatter",
    "no external resources"
  ],
  "notes": "Validation of a bounded subset; not full ECharts semantics or visual correctness."
}
"}
{"id":"chart-document-0.2","language":"en","title":"Experimental 0.2 intent schema","summary":"Experimental 0.2 intent schema","capabilityIds":["basic-0.2"],"schemaVersion":"0.2","source":"packages/schema/src/chart-document-0.2.schema.json","license":"Apache-2.0","updatedAt":"2026-10-31","uri":"chartnexus://schema/chart-document/0.2","contentHash":"sha256:e71c0e98038594544b5f53c03b999d610d8994114f921147caf4aa0d29360103","body":"{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "schemaVersion": {
      "const": "0.2"
    },
    "id": {
      "type": "string",
      "minLength": 1,
      "maxLength": 256
    },
    "mode": {
      "const": "intent"
    },
    "data": {
      "oneOf": [
        {
          "type": "object",
          "additionalProperties": false,
