      "type": "object",
      "additionalProperties": false,
      "properties": {
        "type": {
          "enum": ["bar", "line", "pie", "scatter", "combo", "funnel"]
        },
        "encoding": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "x": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "field": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 128
                },
                "type": {
                  "enum": ["ordinal", "quantitative", "temporal"]
                },
                "temporalKind": {
                  "enum": ["date", "instant"]
