                  "type": "string",
                  "minLength": 1,
                  "maxLength": 128
                },
                "type": {
                  "enum": ["ordinal", "quantitative"]
                },
                "unit": {
                  "oneOf": [
                    {
                      "type": "object",
                      "additionalProperties": false,
                      "properties": {
                        "kind": {
                          "const": "currency"
                        },
                        "code": {
                          "type": "string",
                          "pattern": "^[A-Z]{3}$"
