            "series": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "field": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 128
                }
              },
              "required": ["field"]
            }
          },
          "required": ["x", "y"]
        },
        "stack": {
          "type": "boolean"
        },
        "title": {
          "type": "string",
          "maxLength": 256
        },
        "orientation": {
          "enum": ["vertical", "horizontal"]
        },
        "area": {
          "type": "boolean"
        },
        "donut": {
          "type": "boolean"
        },
        "sort": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "by": {
              "enum": ["category", "value"]
            },
            "order": {
              "enum": ["ascending", "descending"]
            },
            "nulls": {
              "enum": ["first", "last"]
            }
          },
          "required": ["by", "order", "nulls"]
        },
        "aggregate": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "op": {
              "enum": ["sum", "mean", "count"]
            }
          },
          "required": ["op"]
        },
        "secondary": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "field": {
              "type": "string",
              "minLength": 1,
              "maxLength": 128
            },
            "unit": {
              "oneOf": [
                {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "kind": {
                      "const": "currency"
                    },
                    "code": {
                      "type": "string",
                      "pattern": "^[A-Z]{3}$"
                    }
                  },
                  "required": ["kind", "code"]
                },
                {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "kind": {
                      "const": "percent"
                    },
                    "scale": {
                      "enum": ["percent", "ratio"]
                    }
                  },
                  "required": ["kind", "scale"]
                },
                {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "kind": {
                      "const": "unit"
                    },
                    "label": {
                      "type": "string",
                      "minLength": 1,
                      "maxLength": 32
                    }
                  },
                  "required": ["kind", "label"]
                }
              ]
            },
            "axis": {
              "enum": ["shared", "right"]
            }
          },
          "required": ["field"]
        }
      },
      "required": ["type", "encoding"]
    },
    "presentation": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "theme": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "id": {
              "enum": ["light", "dark"]
            },
            "version": {
              "const": "1"
            }
          },
          "required": ["id", "version"]
        },
        "dataLabels": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "show": {
              "type": "boolean"
            }
          },
          "required": ["show"]
        },
        "legend": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "show": {
              "type": "boolean"
            },
            "position": {
              "enum": ["top", "bottom"]
            }
          },
          "required": ["show"]
        }
      }
    }
  },
  "required": ["schemaVersion", "id", "mode", "data", "chart"],
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://chartnexus.dev/schemas/chart-document/0.2",
  "title": "ChartDocument02",
  "description": "Experimental ChartNexus 0.2 intent profile; no network resolution."
}
"}
{"id":"capabilities-0.2","language":"en","title":"Experimental 0.2 capabilities","summary":"Experimental 0.2 capabilities","capabilityIds":["basic-0.2"],"schemaVersion":"0.2","source":"packages/core/src/capabilities-0.2.json","license":"Apache-2.0","updatedAt":"2026-10-31","uri":"chartnexus://capabilities/basic-0.2","contentHash":"sha256:671cd402e27f7e91f5bef69370d9b94caa2f4f9d4a00273ad8aa88166baece33","body":"{
  "id": "basic-0.2",
  "schemaVersion": "0.2",
  "status": "experimental",
  "charts": ["bar", "line", "pie", "scatter", "combo", "funnel"],
  "modes": ["intent"],
  "variants": {
    "bar": ["horizontal"],
    "line": ["area"],
    "pie": ["donut"]
  },
  "themes": [
    {
      "id": "light",
      "version": "1"
    },
    {
      "id": "dark",
      "version": "1"
    }
  ],
  "outputs": ["browser", "svg"],
  "limits": {
    "bytes": 1048576,
    "depth": 32,
    "rows": 10000,
    "series": 50,
    "points": 50000,
    "dimension": 4096
  },
  "sorting": {
    "charts": ["bar", "line", "pie", "funnel"],
    "by": ["category", "value"],
    "orders": ["ascending", "descending"],
    "nulls": ["first", "last"],
    "groupedValue": "unsupported",
    "collation": "utf16-code-unit"
  },
  "units": {
    "charts": ["bar", "line", "scatter"],
    "kinds": ["currency", "percent", "unit"],
    "percentScales": ["percent", "ratio"],
    "conversion": false
  },
  "temporal": {
    "charts": ["line"],
    "kinds": ["date", "instant"],
    "dateFormat": "YYYY-MM-DD",
    "instantFormat": "YYYY-MM-DDTHH:mm:ss[.SSS]Z or ±HH:mm",
    "years": "1000-9999",
    "coordinate": "UTC",
    "displayTimezone": "UTC",
    "namedTimezones": false,
    "numericTimestamps": false
  },
  "aggregation": {
    "charts": ["bar", "line", "pie", "funnel"],
    "operations": ["sum", "mean", "count"],
    "count": "non-null numeric y",
    "allNull": {
      "sum": "null",
      "mean": "null",
      "count": 0
    },
    "identity": "aggregate"
  },
  "presentation": {
    "dataLabels": {
      "show": true,
      "content": "echarts-default",
      "formatter": false
    },
    "legend": {
      "show": true,
      "positions": ["top", "bottom"]
    }
  },
  "combo": {
    "series": ["bar", "line"],
    "axes": ["shared", "right"],
    "x": "ordinal",
    "grouping": false,
    "aggregation": false,
    "units": "shared requires identical or both absent; right requires explicit units for both"
  },
  "funnel": {
    "x": "ordinal",
    "y": "nonnegative",
    "order": "input unless explicitly sorted",
    "conversionRate": "not inferred"
  }
}
"}
